import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Plane mesh for the pricing card background / image
  const planeGeo = new PlaneGeometry(1, 1);
  const planeMat = new MeshBasicNodeMaterial({ color: 0xffffff });
  const planeMesh = new Mesh(planeGeo, planeMat);
  root.add(planeMesh);

  // Load texture if provided
  const disposables = {
    texture: null,
    material: planeMat,
    geometry: planeGeo,
    mesh: planeMesh,
    timeline: null,
  };

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
      disposables.texture = tex;
    });
  }

  // Text content
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txtOpts = {
      fontSize: item.typography?.fontSize ?? 39,
      color: config.colors?.paper ?? '#e8ecf2',
      align: 'center',
    };
    const txtObj = ctx.fontAtlas.createText(item.text, txtOpts);
    // Position text slightly above the plane (z offset)
    txtObj.position.set(0, 0, 0.01);
    root.add(txtObj);
  }

  // Simple entrance animation (rise‑in) using GSAP
  const tl = gsap.timeline();
  tl.from(planeMesh.position, { y: -0.4, duration: 0.7, ease: 'power3.out' });
  tl.from(planeMesh.scale, { x: 0, y: 0, duration: 0.7, ease: 'power3.out' }, '<');
  disposables.timeline = tl;

  // Event handlers placeholder
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Kill GSAP timelines
    if (disposables.timeline) disposables.timeline.kill();

    // Dispose material, geometry, and texture
    if (disposables.material) disposables.material.dispose();
    if (disposables.geometry) disposables.geometry.dispose();
    if (disposables.texture) disposables.texture.dispose();

    // Remove children
    root.traverse((obj) => {
      if (obj !== root) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) obj.material.dispose();
      }
    });
  };

  return root;
}
